import json

# Inspect the current reads and writes
reads = data.get('reads', [])
writes = data.get('writes', [])

# Print facts about the current state
facts = {
    'num_reads': len(reads),
    'num_writes': len(writes),
    'read_results': [],
    'write_details': []
}

for r in reads:
    val = r.get('result')
    # Try to parse if it's a JSON string
    if isinstance(val, str):
        try:
            parsed = json.loads(val)
            facts['read_results'].append({'api': r['api'], 'name': r['name'], 'parsed': parsed})
        except:
            facts['read_results'].append({'api': r['api'], 'name': r['name'], 'raw': val[:200]})
    else:
        facts['read_results'].append({'api': r['api'], 'name': r['name'], 'value': val})

for w in writes:
    facts['write_details'].append({
        'api': w['api'],
        'name': w['name'],
        'args': w.get('args', {}),
        'result': w.get('result')
    })

print(json.dumps({'queries': [], 'facts': facts}))

